entries[227444] = { ["name"] = "Götze der Jägerin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nPrägt Euren Umhang mit der Rune 'Verbesserter Prankenhieb':\n\nIn Katzengestalt wird Eure Fähigkeit 'Prankenhieb' zu 'Prankenhieb (Katze)', in Bärengestalt trifft Eure Fähigkeit 'Prankenhieb' bis zu 7 zusätzliche Gegner.\n\nPrankenhieb (Katze)\n\nSchlägt Gegner in der Nähe, verursacht 250% Waffenschaden und generiert 1 Combopunkt auf Eurem aktiven Ziel.\n\"Tötet 5 schlafende Ziele, während Ihr Euch in der Katzengestalt befindet. Verwendet anschließend diesen Götzen, um eine neue Fertigkeit zu erlernen.\"" }
entries[227451] = { ["name"] = "Sendesiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Symbole \" > v ^ < \" Â sind entlang des Randes eingraviert.\"" }
entries[227454] = { ["name"] = "Gezeitenschleife", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+8 Ausdauer\n+20 Feuerwiderstand\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 13." }
entries[227455] = { ["name"] = "Meeresbrise", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+8 Ausdauer\n+20 Feuerwiderstand\nAnlegen: +22 Angriffskraft." }
entries[227456] = { ["name"] = "Rune des blutroten Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Umhang mit der Rune 'Blutroter Sturm':\n\nEin Finishing-Move, der alle Gegner innerhalb von 8 Metern aufschlitzt und Opfer regelmäßig bluten lässt. Erhöht pro Combopunkt die Dauer und den verursachten Schaden.\n\n1 Punkt: (Angriffskraft * 0.30) Schaden im Verlauf von 4 Sek.\n2 Punkte: (Angriffskraft * 0.45) Schaden im Verlauf von 6 Sek.\n3 Punkte: (Angriffskraft * 0.60) Schaden im Verlauf von 8 Sek.\n4 Punkte: (Angriffskraft * 0.75) Schaden im Verlauf von 10 Sek.\n5 Punkte: (Angriffskraft * 0.90) Schaden im Verlauf von 12 Sek.\n\n'Blutroter Sturm' profitiert von allen Talenten und Effekten die 'Blutung' beeinflussen oder dadurch ausgelöst werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
