entries[227683] = { ["name"] = "Sulfuras, Hand von Ragnaros", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Streitkolben\n229 - 382 Schaden Tempo 3.80\n(80.39 Schaden pro Sekunde)\n+12 Stärke\n+12 Ausdauer\n+32 Feuerwiderstand\nHaltbarkeit 145 / 145\nBenötigt Stufe 60\nAnlegen: +358 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nTrefferchance: Schleudert einen brennenden Ball, der 273 bis 333 Feuerschaden verursacht und die Seele des Ziels reinigt, was dessen erlittenen Feuer- und Heiligschaden um bis zu 30 erhöht und zusätzlich 75 Schaden über 10 Sek. verursacht.\nAnlegen: Chance von 20%, an allen nahen Gegnern 25 Feuerschaden zu verursachen, wenn Ihr von einem Nahkampfangriff getroffen werdet. (Procchance: 20%)" }
entries[227684] = { ["name"] = "Sulfuronhammer", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Streitkolben\n181 - 303 Schaden Tempo 3.80\n(63.68 Schaden pro Sekunde)\n+10 Stärke\n+10 Ausdauer\n+30 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nTrefferchance: Schleudert eine glühende Kugel hinaus, die 83 bis 101 Punkt(e) Feuerschaden sowie zusätzlich 8 Sek. lang 16 Punkt(e) Schaden verursacht.\nAnlegen: Fügt jedem Feind 5 Punkt(e) Feuerschaden zu, der Euch mit einem Nahkampfangriff schlägt.\nAnlegen: +124 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[227685] = { ["name"] = "Modifiziertes Schattenskalpell", ["text"] = "Questgegenstand\nBenutzen: Fokussiert das modifizierte Schattenskalpell auf Arkonos den Verfluchten, um seine schützende Barriere aufzulösen.\n\"Cuthbert hat Daltons letzten Segen auf dieses Instrument übertragen. Hoffentlich gelingt es so, die Barriere einzureißen, die Arkonos schützt.\"" }
