entries[227687] = { ["name"] = "Orthas Lieblingsgoldzahn", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr könnt Orthas Zahn... reiben. Eklig. (2 Min Abklingzeit)\n\"Riecht fürchterlich.\"" }
