entries[227690] = { ["name"] = "Nekrotischer Runenstein", ["text"] = "Questgegenstand\n\"Euch wird speiübel, als Euer nacktes Fleisch mit diesem Runenstein in Kontakt kommt.\"" }
entries[227691] = { ["name"] = "Klinge von Hanna", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nZweihändig Schwert\n101 - 152 Schaden Tempo 2.10\n(60.24 Schaden pro Sekunde)\n+11 Stärke\n+11 Beweglichkeit\n+11 Ausdauer\n+11 Intelligenz\n+11 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 59" }
entries[227724] = { ["name"] = "Blutbeschmierte Belobigung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 30\n\"Einst mag es sich hierbei um eine Auszeichnung gehandelt haben, die für Heldentaten im Kampf verliehen wurde. Auch wenn sie mittlerweile Flecken aufweist und stark mit getrocknetem und verkrustetem Blut überzogen ist, hallt darin vielleicht nach wie vor das leise Echo des Stolzes und der Ehre ihres längst verstorbenen Besitzers wider.\"" }
entries[227727] = { ["name"] = "Pläne: Sulfuronhammer", ["text"] = "Einzigartig\nBenötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Sulfuronhammers.\nSulfuronhammer\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n181 - 303 Schaden Tempo 3.80\n(63.68 Schaden pro Sekunde)\n+10 Stärke\n+10 Ausdauer\n+30 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nTrefferchance: Schleudert eine glühende Kugel hinaus, die 83 bis 101 Punkt(e) Feuerschaden sowie zusätzlich 8 Sek. lang 16 Punkt(e) Schaden verursacht.\nAnlegen: Fügt jedem Feind 5 Punkt(e) Feuerschaden zu, der Euch mit einem Nahkampfangriff schlägt.\nAnlegen: +124 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenötigt Sulfuronblock (8), Dunkeleisenbarren (20), Arkanitbarren (50), Essenz des Feuers (25), Blut des Berges (10), Lavakern (10), Feuerkern (10)" }
entries[227728] = { ["name"] = "Auge von Sulfuras", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Das Auge von Sulfuras kann mit dem Sulfuronhammer kombiniert werden, um Sulfuras zu erschaffen, den legendären Hammer von Ragnaros." }
entries[227730] = { ["name"] = "Vertrag der Thoriumbruderschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n\"Gebunden in Dunkeleisendraht\"" }
