entries[227748] = { ["name"] = "Tagebuch des Überlebenden", ["text"] = "Questgegenstand\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[227749] = { ["name"] = "Rune der Sternschnuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euren Umhang mit der Rune\n'Sternenregen':\n\nIhr beschwört einen Sternenschauer vom Himmel, der 10 Sek. lang anhält und auf Ziele innerhalb von 30 Metern um Eure Position herniedergeht. Jeder Stern fügt seinem Ziel [Quellwert] bis [Quellwert] Arkanschaden sowie allen anderen Gegnern innerhalb von 5 Metern [Quellwert] Arkanschaden zu. Es werden maximal 20 Sterne beschworen.\n\nGestaltwandel oder Aufsitzen brechen den Effekt ab. Jedweder Effekt, der Euch die Kontrolle über Euren Charakter verlieren lässt, führt zum Abbruch von 'Sternenregen'.\n\nProfitiert von den meisten Talenten und Effekten und löst diese aus, die auch 'Mondfeuer' auslösen oder davon profitieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
