entries[227811] = { ["name"] = "Verteidiger der Holzschlundfeste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Holzschlundfeste\n- Ehrfürchtig\nBenutzen: Ruft einen Vorfahren der Holzschlundfeste herbei, der an Eurer Seite kämpft und Euch heilt. (10 Min Abklingzeit)" }
