entries[227922] = { ["name"] = "Rune des Schwadroneurs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Umhang mit der Rune 'Donnerbüchse':\n\nFeuert einen Musketenschuss auf bis zu 4 Gegner und verursacht in einem kegelförmigen Bereich vor dem Schurken [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Angriffskraft] bis [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Angriffskraft] körperlichen Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
