entries[228115] = { ["name"] = "Muster: Synthetischer Ogeranzug der Gordok", ["text"] = "Wird beim Anlegen gebunden\nZweihändig\n153 - 256 Schaden Tempo 3.80\n(53.82 Schaden pro Sekunde)\n+13 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 58\nBenutzen: Lehrt Euch, wie man einen unbeständigen Umhang herstellt.\nSynthetischer Ogeranzug der Gordok\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Verkleidet euch als Oger der Gordok und täuscht vielleicht sogar einen gewissen Captain! Der Anzug hält nur für 10 Min.. (10 Min Abklingzeit)\n\"Hebt, stützt UND riecht nicht nach Oger... also kaum!\"\nBenötigt Unverwüstliches Leder (4), Runenstoffballen (2), Ogergerbemittel , Runenfaden" }
