entries[228117] = { ["name"] = "Pläne: Veredelter Arkanitchampion", ["text"] = "Benötigt Schmiedekunst (300)\nBenötigt Schwertschmiedemeister\nBenutzen: Lehrt Euch, wie man eine Arkanitchampion herstellt.\nVeredelter Arkanitchampion\nWird beim Anlegen gebunden\nZweihändig Schwert\n107 - 161 Schaden Tempo 2.00\n(67.00 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 60\nTrefferchance: Sich selbst um 270 bis 450 heilen und Stärke 30 Sek. lang um 120 Punkt(e) erhöhen.\nTrefferchance: Erhöht den verursachten Schaden um 20 und das Angriffstempo um 5%. Hält 15 Sek. lang an.\nBenötigt Arkanitchampion , Elementarwetzstein (10)" }
entries[228118] = { ["name"] = "Pläne: Festerungsstulpen", ["text"] = "Benötigt Schmiedekunst (300)\nBenötigt Rüstungsschmied\nBenutzen: Lehrt Euch die Herstellung von Festungsstulpen.\nFestungsstulpen\nWird beim Anlegen gebunden\nHände Platte\n441 Rüstung\n+12 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 57\nAnlegen: Immun gegen Entwaffnen.\nAnlegen: Erhöht Eure Chance, einen Angriff zu parieren, um 1%.\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\nBenötigt Arkanitbarren (15), Verzauberter Thoriumbarren (20), Essenz der Erde (10), Blauer Saphir (4), Großer Opal (4)" }
entries[228119] = { ["name"] = "Muster: Teufelskernstulpen", ["text"] = "Benötigt Lederverarbeitung (290)\nBenötigt Stammeslederverarbeitung\nBenutzen: Lehrt Euch, wie man Teufelskernstulpen herstellt.\nTeufelskernstulpen\nWird beim Anlegen gebunden\nHände Leder\n123 Rüstung\n+12 Ausdauer\n+15 Feuerwiderstand\nHaltbarkeit 40 / 40\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: +38 Angriffskraft.\n\nTeufelsaurierrüstung (0/2)\nTeufelskernstulpen\nTeufelskerngamaschen\nBenötigt Unverwüstliches Leder (30), Teufelssaurierleder (8), Runenfaden , Essenz des Feuers (8)" }
