entries[228123] = { ["name"] = "Frohlockende Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Umhang mit der Rune 'Verbindende Heilung':\n\nHeilt ein verbündetes Ziel und den Zaubernden um [Quellwert] bis [Quellwert] Gesundheit. Niedrige Bedrohung. Dieser Zauber profitiert von allen Effekten, die mit 'Blitzheilung' verbunden sind, und löst diese aus.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[228124] = { ["name"] = "Traumartige Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Umhang mit der Rune 'Seelenwehr':\n\nEuer 'Machtwort: Schild' hat keine Abklingzeit mehr, kostet 15% weniger Mana, gewährt 10% zusätzlichen Basiswert und erhöht Eure Heilkraft um 10%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
