entries[229374] = { ["name"] = "Fäuste der Feueranbeter", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nEinhändig Streitkolben\n59 - 110 Schaden Tempo 1.70\n(49.71 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 2%.\nTrefferchance: Überzieht den Gegner mit 70 Feuerschaden." }
entries[229376] = { ["name"] = "Zauberdolch", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Dolch\n36 - 78 Schaden Tempo 1.40\n(40.71 Schaden pro Sekunde)\n60 Rüstung\n+8 Ausdauer\n+16 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 36." }
entries[229377] = { ["name"] = "Magmadars linke Klaue", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchildhand Faustwaffe\n92 - 171 Schaden Tempo 2.50\n(52.60 Schaden pro Sekunde)\n+11 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\nRuf des Kernhunds (0/3)\nMagmadars rechte Klaue\nMagmadars linke Klaue\nMagmadars Horn\n(2) Set : Bei Nahkampftreffern besteht eine geringe Chance, einen Kernhund herbeizurufen, der 1 Min. lang bestehen bleibt. (Procchance: 1%, 1Min. Abklingzeit)\n(3) Set : Bei Nahkampftreffern besteht eine geringe Chance, den Geist Magmadars herbeizurufen, der Euch im Kampf unterstützt. Erhöht Euer Angriffstempo für 20 Sek. um 10%. (Procchance: 1%, 1Min. Abklingzeit)" }
entries[229378] = { ["name"] = "Magmadars rechte Klaue", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Faustwaffe\n92 - 171 Schaden Tempo 2.50\n(52.60 Schaden pro Sekunde)\n+12 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +20 Angriffskraft.\n\nRuf des Kernhunds (0/3)\nMagmadars rechte Klaue\nMagmadars linke Klaue\nMagmadars Horn\n(2) Set : Bei Nahkampftreffern besteht eine geringe Chance, einen Kernhund herbeizurufen, der 1 Min. lang bestehen bleibt. (Procchance: 1%, 1Min. Abklingzeit)\n(3) Set : Bei Nahkampftreffern besteht eine geringe Chance, den Geist Magmadars herbeizurufen, der Euch im Kampf unterstützt. Erhöht Euer Angriffstempo für 20 Sek. um 10%. (Procchance: 1%, 1Min. Abklingzeit)" }
entries[229379] = { ["name"] = "Eskhandars rechte Klaue", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Faustwaffe\n87 - 163 Schaden Tempo 2.60\n(48.08 Schaden pro Sekunde)\n+7 Beweglichkeit\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nTrefferchance: Erhöht Euer Angriffstempo 5 Sek. lang um 25%.\n\nSeele des Eskhandar (0/4)\nEskhandars rechte Klaue\nEskhandars linke Klaue\nEskhandars Pelz\nEskhandars Halsband\n(2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(3) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(4) Set : 1% Chance bei einem Nahkampftreffer den Geist von Eskhandar herbeizurufen, der Euch 2 Min. lang im Kampf unterstützt. (Procchance: 1%, 1Min. Abklingzeit)" }
entries[229380] = { ["name"] = "Schattenschlag", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nZweihändig Stangenwaffe\n186 - 279 Schaden Tempo 3.40\n(68.38 Schaden pro Sekunde)\n+33 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\nTrefferchance: Stiehlt dem gegnerischen Ziel 180 bis 220 Leben.\nAnlegen: +189 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Transformiert 'Schattenschlag' zu 'Donnerschlag'. (1 Min Abklingzeit)" }
entries[229381] = { ["name"] = "Donnerschlag", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nZweihändig Stangenwaffe\n186 - 279 Schaden Tempo 3.40\n(68.38 Schaden pro Sekunde)\n+13 Beweglichkeit\n+33 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\nTrefferchance: Überzieht bis zu 3 Ziele mit 200 bis 300 Naturschaden. Der angerichtete Schaden verringert sich jedoch von Ziel zu Ziel.\nAnlegen: +189 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Transformiert 'Donnerschlag' zu 'Schattenschlag'. (1 Min Abklingzeit)" }
entries[229382] = { ["name"] = "Überwärmter Isolierlavagreifer", ["text"] = "Geschmolzen\nWird beim Aufheben gebunden\nZweihändig Streitkolben\n140 - 227 Schaden Tempo 3.20\n(57.34 Schaden pro Sekunde)\n+25 Ausdauer\n+24 Intelligenz\n+15 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 84.\nAnlegen: Stellt alle 5 Sek. 9 Punkt(e) Mana wieder her.\n\"Eigentum von Pip Quickwit, Großmeister Abenteurer\"" }
entries[229415] = { ["name"] = "Überlebensvorräte", ["text"] = "Questgegenstand\nBenutzen: Legt ein Fundament für einen Überlebenslagerplatz. Bringt weitere Vorräte an diesen Lagerplatz, um einen Unterstand zu bauen. (5 Min Abklingzeit)" }
entries[229416] = { ["name"] = "Warmes Fell", ["text"] = "Questgegenstand" }
entries[229749] = { ["name"] = "Wahrheitsbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blazefury] (1)\nZweihändig Schwert\n132 - 199 Schaden Tempo 2.10\n(78.81 Schaden pro Sekunde)\n+30 Stärke\n+21 Beweglichkeit\n+16 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Fügt Euren Nahkampfangriffen 4 Heiligschaden hinzu.\nTrefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\nBenutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Anderthalbhänder zu führen, damit Ihr ihn zusammen mit einem Schild einsetzen könnt. (1 Min Abklingzeit)" }
entries[229806] = { ["name"] = "Wahrheitsbringer", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Schwert\n63 - 118 Schaden Tempo 1.50\n(60.33 Schaden pro Sekunde)\n+14 Ausdauer\n+12 Intelligenz\nHaltbarkeit 105 / 105\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 144 und den verursachten Schaden um bis zu 77.\nTrefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\nBenutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Zweihandschwert zu führen. (1 Min Abklingzeit)" }
entries[229894] = { ["name"] = "Traumsmaragd", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht dauerhaft Euren Ruf beim Zirkel des Cenarius." }
entries[229897] = { ["name"] = "Rolle: Siegel der Anrufung herstellen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Zirkel des Cenarius\n- Freundlich\nBenutzen: Mit 1 Dunkelrune und 5 Feuerblüten kombinieren, um ein Siegel der Anrufung: Feuer herzustellen." }
entries[229906] = { ["name"] = "Trübe Bronzeschuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Gewährt eine Chance, seltsame oder übersehene Gegenstände zu bemerken, die von mächtigen Gegnern fallen gelassen wurden.\nBenutzen: Reist an einen Ort außerhalb der Zeit. Ihr müsst Euch dafür in Tanaris befinden. (5 Min Abklingzeit)" }
entries[229909] = { ["name"] = "Stab der Ordnung", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n140 - 241 Schaden Tempo 3.20\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\nAnlegen: Immer, wenn Ihr einem Ziel Arkanschaden zufügt, wird die verbleibende Abklingzeit von 'Geistesgegenwart' um 1 Sek. verringert.\nBenutzen: Stimmt Euren Stab auf Feuermagie ab. (1 Min Abklingzeit)" }
entries[229910] = { ["name"] = "Sense des Chaos", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n140 - 241 Schaden Tempo 3.20\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\nAnlegen: Chance bei direkten Schadenszaubern, Eure nächste Beschwörung eines Begleiters innerhalb von 20 Sek. zu einem Spontanzauber zu machen und keinen Seelensplitter zu kosten. (Procchance: 10%, 1Min. Abklingzeit)\nBenutzen: Erntet die Seele des von Euch beschworenen Dämons, wodurch Euch ein Effekt gewährt wird, der 15 Sek. lang anhält. Der Effekt wird abgebrochen, wenn ein Dämon beschworen wird. (1 Min Abklingzeit)" }
entries[229911] = { ["name"] = "Caius' Traumfresser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[229964] = { ["name"] = "Huf eines Dämonenlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60" }
entries[229965] = { ["name"] = "Das Auge von Az'olgothal", ["text"] = "Questgegenstand\nEinzigartig\n\"Die letzte nachhallende Kugel gärt vor Teufelsenergie. Es ist, als wüsste sie, dass Ihr sie zerstören wollt, und verströmt im Gegenzug verächtlichen Hass gegen Euch.\"" }
entries[229966] = { ["name"] = "Halsreif der Silbernen Hand", ["text"] = "Wird beim Aufheben gebunden\nHals\n+10 Stärke\n+5 Ausdauer\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[229971] = { ["name"] = "Stab des Infernos", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n140 - 241 Schaden Tempo 3.20\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\nAnlegen: Wenn 'Verbessertes Versengen' als Talent ausgewählt ist, werden Ziele, die von Eurer 'Druckwelle' getroffen werden, zusätzlich mit 5 Stapeln von 'Feuerverwundbarkeit' belegt.\nBenutzen: Stimmt Euren Stab auf Frostmagie ab. (1 Min Abklingzeit)" }
entries[229972] = { ["name"] = "Stab des Raureifs", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n140 - 241 Schaden Tempo 3.20\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\nAnlegen: Erhöht den von Frostzaubern und -effekten verursachten Schaden um bis zu 100, während 'Eisbarriere' aktiv ist.\nBenutzen: Stimmt Euren Stab auf Arkanmagie ab. (1 Min Abklingzeit)" }
entries[230002] = { ["name"] = "Tödlicher Vollender", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Axt\n123 - 229 Schaden Tempo 2.90\n(60.69 Schaden pro Sekunde)\n+13 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nTrefferchance: Schleudert einen Gegner mit einem schnellen Aufwärtshaken in die Luft." }
entries[230003] = { ["name"] = "Hammer des Lichtbringers", ["text"] = "Der Brand von Andorhal\nWird beim Aufheben gebunden\nZweihändig Schwert\n310 - 466 Schaden Tempo 4.00\n(97.00 Schaden pro Sekunde)\n+14 Stärke\n+20 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nTrefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\nAnlegen: Fügt Euren Nahkampfangriffen 4 Heiligschaden hinzu.\nBenutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Anderthalbhänder zu führen, damit Ihr ihn zusammen mit einem Schild einsetzen könnt. (1 Min Abklingzeit)\n\"Diese Waffe zu halten, fühlt sich für Euch irgendwie falsch an. Sie sollte hier verbleiben, wo sie ihrem Besitzer aus der Hand glitt, als der seinen letzten Atemzug tat.\"" }
entries[230018] = { ["name"] = "Kugelfragmente der Mannoroc", ["text"] = "Questgegenstand\nEinzigartig" }
entries[230224] = { ["name"] = "Donnerzorn, gesegnete Klinge des Windsuchers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n82 - 153 Schaden Tempo 1.90\n(61.84 Schaden pro Sekunde)\n+5 Beweglichkeit\n+8 Ausdauer\n+8 Feuerwiderstand\n+9 Naturwiderstand\nHaltbarkeit 125 / 125\nBenötigt Stufe 60\nTrefferchance: Deckt Euren Gegner mit Blitzschlägen ein, die 300 Naturschaden verursachen und auf Gegner in der Nähe überspringen. Jeder Sprung verringert den Naturwiderstand des Ziels um 25. Wirkt auf insgesamt 5 Ziele. Euer Hauptziel wird außerdem von einem Wirbelsturm umgeben, welcher dessen Angriffstempo 12 Sek. lang um 20% verringert." }
entries[230237] = { ["name"] = "Edelstein der arkanen Kraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Jäger\nBenötigt Stufe 60\nBenutzen: Erfüllt Euch mit arkaner Energie, wodurch Eure Einsätze von 'Zerlegen' und 'Mehrfachschuss' in den nächsten 15 Sek. bis zu 5 Detonationen pro Einsatz erzeugen. 'Arkane Detonation' fügt Gegnern in der Nähe des Ziels 185 bis 215 Schaden zu. (1 Min, 30 Sek. Abklingzeit)" }
entries[230238] = { ["name"] = "Das schwarze Buch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Erfüllt Euren Begleiter mit Macht, erhöht 30 Sek. lang dessen Schaden um 100% und dessen Rüstung um 100%. Die Zauber betrifft vorübergehende Begleiter oder unterworfene Dämonen nicht. (3 Min Abklingzeit)" }
