entries[230242] = { ["name"] = "Die ungezähmte Klinge", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n198 - 297 Schaden Tempo 3.50\n(70.71 Schaden pro Sekunde)\n+29 Beweglichkeit\n+20 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nTrefferchance: Erhöht die Stärke 8 Sek. lang um 300." }
entries[230243] = { ["name"] = "Edelstein des Gedankensprungs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Beschleunigt die Gedanken und erhöht somit die Zaubergeschwindigkeit des Magiers 20 Sek. lang um 33%. (2 Min Abklingzeit)" }
entries[230244] = { ["name"] = "Siegel des Gestaltwandlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Druide\nBenötigt Stufe 60\nBenutzen: Verringert die Manakosten aller Formen des Gestaltwandels des Druiden um 100% und erhöht den Auraeffekt von 'Aura des Mondkin', 'Baum des Lebens' und 'Rudelführer' 20 Sek. lang um 100%. (2 Min Abklingzeit)" }
