entries[230248] = { ["name"] = "Roter Drachenschuppenbeschützer", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n2787 Rüstung\n51 Blocken\n+6 Ausdauer\n+10 Intelligenz\n+5 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 40 und den verursachten Schaden um bis zu 14." }
entries[230249] = { ["name"] = "Lebensspendender Edelstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Krieger\nBenötigt Stufe 60\nBenutzen: Heilt Euch um 15% Eurer maximalen Gesundheit und erhöht Eure maximale Gesundheit 20 Sek. lang um 15%. (2 Min Abklingzeit)" }
